module tb;
    logic clk;
    logic w;
    logic R;
    logic E;
    logic L;
    logic Q;

    TopModule uut (
        .clk(clk),
        .w(w),
        .R(R),
        .E(E),
        .L(L),
        .Q(Q)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        w = 0;
        R = 0;
        E = 0;
        L = 0;

        // Test 1: Hold (L=0, E=0)
        @(posedge clk);
        #1;
        if (Q !== 0) begin
            $display("SELFTEST FAIL: Hold failed at t=%0t", $time);
            $finish;
        end

        // Test 2: Load R=1 (L=1)
        L = 1;
        R = 1;
        @(posedge clk);
        #1;
        if (Q !== 1) begin
            $display("SELFTEST FAIL: Load failed, expected Q=1, got %b at t=%0t", Q, $time);
            $finish;
        end

        // Test 3: Hold when L=0, E=0 even if w=1, R=0
        L = 0;
        E = 0;
        w = 1;
        R = 0;
        @(posedge clk);
        #1;
        if (Q !== 1) begin
            $display("SELFTEST FAIL: Hold with disabled shift failed, expected Q=1, got %b at t=%0t", Q, $time);
            $finish;
        end

        // Test 4: Shift w=0 (E=1, L=0)
        E = 1;
        w = 0;
        @(posedge clk);
        #1;
        if (Q !== 0) begin
            $display("SELFTEST FAIL: Shift w=0 failed, expected Q=0, got %b at t=%0t", Q, $time);
            $finish;
        end

        // Test 5: Shift w=1 (E=1, L=0)
        w = 1;
        @(posedge clk);
        #1;
        if (Q !== 1) begin
            $display("SELFTEST FAIL: Shift w=1 failed, expected Q=1, got %b at t=%0t", Q, $time);
            $finish;
        end

        // Test 6: Load takes precedence over E
        L = 1;
        E = 1;
        R = 0;
        w = 1;
        @(posedge clk);
        #1;
        if (Q !== 0) begin
            $display("SELFTEST FAIL: Load precedence failed, expected Q=0, got %b at t=%0t", Q, $time);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

